export class ApiError extends Error {
  constructor(
    message: string,
    public readonly issues: Record<string, string> = {},
    public readonly status = 500,
    public readonly technicalDetail = message,
    public readonly recovery:AiRuntimeRecovery|null=null,
  ) {
    super(message);
  }
}

const PRIVATE_RUNTIME_MANIFEST_ERROR = "私有运行包 manifest 不存在或不是受控普通文件；禁止从系统 PostgreSQL 回退。";

export function safeRecoveryTarget(candidate: unknown): AiRuntimeRecovery | null {
  if (!candidate || typeof candidate !== "object") return null;
  const value = candidate as Record<string, unknown>;
  if (typeof value.failedStep !== "string" || typeof value.summary !== "string" || typeof value.savedResult !== "string" || typeof value.sourceRoute !== "string" || typeof value.actionLabel !== "string") return null;
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const composition = value.sourceRoute === COMPOSITION_ROUTE || (value.sourceRoute.startsWith(`${COMPOSITION_ROUTE}?previewId=`) && uuid.test(value.sourceRoute.slice(`${COMPOSITION_ROUTE}?previewId=`.length)));
  const writingParts=/^\/new-design\/books\/([^/?#]+)\/writing\?chapterDocument=([^&#]+)&session=([^&#]+)$/.exec(value.sourceRoute);
  const writing=writingParts&&writingParts.slice(1).every(part=>uuid.test(part))&&value.actionLabel==="返回章节结算";
  const chapterWritingParts=/^\/new-design\/books\/([^/?#]+)\/writing\?chapter=([^&#]+)$/.exec(value.sourceRoute);
  const chapterWriting=chapterWritingParts&&chapterWritingParts.slice(1).every(part=>uuid.test(part))&&value.actionLabel==="返回章节创作";
  const relationParts=/^\/new-design\/structure\/dictionaries-relations\?view=relations(?:&book=([^&#]+)(?:&chapterDocument=([^&#]+)&session=([^&#]+))?)?$/.exec(value.sourceRoute);
  const relation=relationParts&&relationParts.slice(1).filter(part=>part!==undefined).every(part=>uuid.test(part))&&value.actionLabel==="打开关系配置";
  const creation=value.sourceRoute==="/new-design/books/new"||value.sourceRoute.startsWith("/new-design/books/new?session=")&&uuid.test(value.sourceRoute.slice("/new-design/books/new?session=".length));
  const knowledgeParts=/^\/new-design\/knowledge\?bookId=([^&#]+)$/.exec(value.sourceRoute);
  const knowledge=knowledgeParts&&uuid.test(knowledgeParts[1])&&value.actionLabel==="返回知识参考";
  const viewParts=/^\/new-design\/books\/([^/?#]+)\/views\/(chapters|characters|relations|events|clues|props|states|rules|comparison|quality|world|resources)$/.exec(value.sourceRoute);
  const views=viewParts&&uuid.test(viewParts[1])&&value.actionLabel==="返回多维视图";
  const records=value.sourceRoute==="/new-design/operations/records"&&value.actionLabel==="打开运行记录";
  const materialParts=/^\/new-design\/books\/([^/?#]+)\/cards$/.exec(value.sourceRoute);
  const materials=materialParts&&uuid.test(materialParts[1])&&value.actionLabel==="返回本书资料";
  const publicCharacters=value.sourceRoute==="/new-design/resources/characters/workshop"&&value.actionLabel==="返回公共角色试用";
  const professional=value.sourceRoute===PROFESSIONAL_ROUTE&&value.actionLabel==="返回专业创作资源";
  const bookCompositionParts=/^\/new-design\/books\/([^/?#]+)\/composition$/.exec(value.sourceRoute);
  const bookComposition=bookCompositionParts&&uuid.test(bookCompositionParts[1])&&value.actionLabel==="返回全书编排";
  const directorParts=/^\/new-design\/books\/([^/?#]+)\/director(?:\?run=([^&#]+))?$/.exec(value.sourceRoute);
  const director=directorParts&&directorParts.slice(1).filter(part=>part!==undefined).every(part=>uuid.test(part))&&value.actionLabel==="返回全书导演";
  const visualParts=/^\/new-design\/books\/([^/?#]+)\/visual-assets$/.exec(value.sourceRoute);
  const visual=visualParts&&uuid.test(visualParts[1])&&(value.actionLabel==="返回本书视觉资产"||value.actionLabel==="返回本书图片");
  const worldParts=/^\/new-design\/books\/([^/?#]+)\/world(?:\?check=([^&#]+))?$/.exec(value.sourceRoute);
  const world=worldParts&&worldParts.slice(1).filter(part=>part!==undefined).every(part=>uuid.test(part))&&value.actionLabel==="返回世界维护";
  const extractionParts=/^\/new-design\/resources\/extraction\?bookId=([^&#]+)(?:&previewId=([^&#]+))?$/.exec(value.sourceRoute);
  const extraction=extractionParts&&extractionParts.slice(1).filter(part=>part!==undefined).every(part=>uuid.test(part))&&value.actionLabel==="返回创作提炼";
  const imageConfiguration=value.sourceRoute==="/new-design/structure/models"&&value.actionLabel==="打开新设计模型设置";
  const directorControl=value.sourceRoute==="/new-design/operations/director"&&value.actionLabel==="返回导演总控台";
  const professionalGraphParts=/^\/new-design\/books\/([^/?#]+)\/professional-views$/.exec(value.sourceRoute);
  const professionalGraph=professionalGraphParts&&uuid.test(professionalGraphParts[1])&&value.actionLabel==="返回专业图形视图";
  const dialogueParts=/^\/new-design\/books\/([^/?#]+)\/character-dialogue(?:\?session=([^&#]+)(?:&round=([^&#]+))?)?$/.exec(value.sourceRoute);
  const dialogue=dialogueParts&&dialogueParts.slice(1).filter(part=>part!==undefined).every(part=>uuid.test(part))&&value.actionLabel==="返回人物对话模拟";
  const maintenanceParts=/^\/new-design\/books\/([^/?#]+)\/(world|characters)$/.exec(value.sourceRoute);
  const professionalMaintenance=maintenanceParts&&uuid.test(maintenanceParts[1])&&value.actionLabel==="返回专业维护";
  const contextRunParts=/^\/new-design\/structure\/context\?bookId=([^&#]+)&tab=run$/.exec(value.sourceRoute);
  const contextRun=contextRunParts&&uuid.test(contextRunParts[1])&&value.actionLabel==="返回运行输入";
  const fieldRoute=/^\/new-design\/books\/([0-9a-f-]+)\/story-setting$/.exec(String(value.sourceRoute));
  const fieldRecovery=fieldRoute&&uuid.test(fieldRoute[1])&&value.actionLabel==="返回资料填写";
  const structure=(value.sourceRoute==="/new-design/structure/forms"&&value.actionLabel==="返回创作表单")||(value.sourceRoute==="/new-design/structure/templates"&&value.actionLabel==="返回开书模板");
  const allowed = (value.sourceRoute === "/new-design/structure/models" && value.actionLabel === "打开模型设置") || (value.sourceRoute === "/new-design/structure/maintenance" && value.actionLabel === "打开运行维护") || (composition && value.actionLabel === "返回提示词组合") || writing || chapterWriting || relation || knowledge || views || records || materials || professional || publicCharacters || bookComposition || director || visual || world || extraction || imageConfiguration || directorControl || professionalMaintenance || contextRun || structure || creation&&value.actionLabel==="返回开书表单";
  return allowed||professionalGraph||dialogue||fieldRecovery ? value as unknown as AiRuntimeRecovery : null;
}

export function isGlobalModelRecovery(recovery: AiRuntimeRecovery): boolean {
  return recovery.sourceRoute === "/new-design/structure/models" || recovery.sourceRoute === "/new-design/structure/maintenance";
}

function publicApiErrorMessage(message: string, status: number): string {
  return message === PRIVATE_RUNTIME_MANIFEST_ERROR
    ? "数据服务暂未就绪，请到“运行维护”查看状态。"
    : publicServiceError(message, status);
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response:Response;
  try {
    response = await fetch(`${API_ROOT}${path}`, {
      ...init,
      headers: { "Content-Type": "application/json", ...init?.headers },
    });
  } catch {
    throw new ApiError("未能连接数据服务。请打开“运行维护”检查连接；提交过的操作需先核对结果，不要连续重复点击。",{},503);
  }
  let envelope:ApiEnvelope<T>&{recovery?:AiRuntimeRecovery};
  try {
    const decoded:unknown=await response.json();
    if(decoded===null||typeof decoded!=="object"||typeof(decoded as ApiEnvelope<T>).success!=="boolean")throw new Error("Invalid response envelope");
    envelope=decoded as ApiEnvelope<T>&{recovery?:AiRuntimeRecovery};
  } catch {
    throw new ApiError("未收到有效的服务器回执。请保留当前编辑，先核对服务器结果；读取操作可重试读取。",{},502);
  }
  if(response.ok&&envelope.success&&envelope.data===undefined)throw new ApiError("服务器未返回操作结果。请保留编辑，先核对服务器结果，不要连续重复提交。",{},502);
  if (!response.ok || !envelope.success || envelope.data === undefined) {
    const technicalDetail = envelope.error ?? "请求失败，请稍后重试。";
    const candidate=envelope.recovery;
    const recovery=safeRecoveryTarget(candidate);
    if(recovery&&isGlobalModelRecovery(recovery)&&typeof window!=="undefined")window.dispatchEvent(new CustomEvent("new-design:model-failure",{detail:recovery}));
    throw new ApiError(recovery?`${recovery.failedStep}失败：${recovery.summary}`:publicApiErrorMessage(technicalDetail, response.status), envelope.issues, response.status, technicalDetail,recovery);
  }
  return envelope.data;
}

